# app.R — ShinyLive-ready CI visualizer (fixed x-axis, n ≤ 150)
library(shiny)
library(bslib)

# --- OUP colour palette --------------------------------------------------
OUP_BACKGROUND  <- "#DFDFDF"  # page, plot and input backgrounds
OUP_VALUE_BOX   <- "#CECECE"  # slider value boxes and secondary controls
OUP_BORDER      <- "#8C8C8C"  # plot and control borders
OUP_RED         <- "#8A1E00"  # mean and primary emphasis
OUP_BROWN       <- "#BE5A16"  # sliders, handles and control focus
OUP_ORANGE      <- "#E57726"  # density curve and confidence-interval endpoints
OUP_TRACK_GREY  <- "#AFAFAF"  # inactive slider track
OUP_TEXT        <- "#000000"  # text, axes and labels

# Theme (no font_google; set fonts via CSS variables)
oup_theme <- bs_theme(
  version   = 5,
  bg        = OUP_BACKGROUND,
  fg        = OUP_TEXT,
  primary   = OUP_BROWN,
  secondary = OUP_VALUE_BOX
) |>
  bs_add_rules("
    :root{
      --bs-body-font-family: 'Lexend', system-ui, -apple-system, Segoe UI, Roboto, 'Helvetica Neue', Arial, sans-serif;
      --bs-font-monospace: 'Recursive', ui-monospace, SFMono-Regular, Menlo, Consolas, 'Liberation Mono', monospace;
    }
  ") |>
  bs_add_rules(paste0("
    .container-fluid { max-width: 1100px; }
    .shiny-input-container { margin-bottom: 10px; }

    .container-fluid{
      padding-top: 16px;
      padding-top: calc(16px + env(safe-area-inset-top));
      padding-bottom: 22px;
      padding-bottom: calc(22px + env(safe-area-inset-bottom));
    }

    .no-stack { display: flex; gap: 16px; align-items: flex-start; }
    .no-stack .left  { flex: 0 0 320px; min-width: 260px; }
    .no-stack .right { flex: 1 1 auto; min-width: 0; }

    .no-stack .left .shiny-input-container .control-label { margin-top: 16px; }
    .no-stack .left .shiny-input-container:first-of-type .control-label { margin-top: 50px; }
    .no-stack .left .sidebar-title { margin-top: 16px; font-weight: 600; }

    .legend-dot {
      display:inline-block; width:14px; height:14px; border-radius:50%;
      margin-right:6px; vertical-align:middle; border:1px solid #8C8C8C;
    }
    .legend-item { margin-bottom: 6px; }

    #stats { font-size: 16px; font-weight: 500; line-height: 1.35;
             margin-top: 0px; padding-top: 0px; overflow-wrap: anywhere; }

    #plotBox{
      background: ", OUP_BACKGROUND, " !important;
      border: 2px solid ", OUP_BORDER, " !important;
      padding: 12px;
      border-radius: .6rem;
      box-shadow: none;
      margin-top: 15px;
      margin-bottom: 0;
      padding-bottom: 18px;
    }

    .form-control, .form-select, .selectize-input{
      background-color: ", OUP_BACKGROUND, " !important;
      color: ", OUP_TEXT, " !important;
      border: 1px solid ", OUP_BACKGROUND, " !important;
      box-shadow: none !important;
    }
    .form-control:focus, .form-select:focus, .selectize-input.focus{
      border-color: ", OUP_BROWN, " !important;
      outline: 0 !important;
      box-shadow: 0 0 0 .15rem rgba(190,90,22,.35) !important;
    }
    .selectize-dropdown, .selectize-dropdown .active{
      background: ", OUP_BACKGROUND, " !important;
      color: ", OUP_TEXT, " !important;
      border-color: ", OUP_BORDER, " !important;
    }

    .irs--shiny .irs-single, .irs--shiny .irs-from, .irs--shiny .irs-to,
    .irs--shiny .irs-min, .irs--shiny .irs-max { font-size: 13px; font-weight: 600; }
    .irs--shiny .irs-grid, .irs--shiny .irs-grid-text,
    .irs--shiny .irs-grid-pol, .irs--shiny .irs-grid-pol.small { display: none !important; }
    .irs--shiny.irs-with-grid { height: 44px; }

    .irs--shiny .irs-bar,
    .irs--shiny .irs-bar-edge {
      background: ", OUP_BROWN, " !important;
      border-color: ", OUP_BROWN, " !important;
    }
    .irs--shiny .irs-line {
      background: ", OUP_TRACK_GREY, " !important;
      border-color: ", OUP_TRACK_GREY, " !important;
    }
    .irs--shiny .irs-handle,
    .irs--shiny .irs-handle > i:first-child {
      background: ", OUP_BROWN, " !important;
      border-color: ", OUP_BROWN, " !important;
      box-shadow: none !important;
    }
    .irs--shiny .irs-single,
    .irs--shiny .irs-from,
    .irs--shiny .irs-to {
      background: ", OUP_VALUE_BOX, " !important;
      color: ", OUP_TEXT, " !important;
    }
    .irs--shiny .irs-single::before,
    .irs--shiny .irs-from::before,
    .irs--shiny .irs-to::before {
      border-top-color: ", OUP_VALUE_BOX, " !important;
    }
    .irs--shiny .irs-min,
    .irs--shiny .irs-max {
      background: transparent !important;
      color: ", OUP_TEXT, " !important;
    }

    @media (max-width: 576px){
      .no-stack{ flex-direction: column; gap: 12px; }
      .no-stack .left, .no-stack .right{ flex: 1 1 100%; min-width: 0; }
      .container-fluid{ padding-left: 12px; padding-right: 12px; }
      .no-stack .left .shiny-input-container .control-label { margin-top: 12px; }
      .no-stack .left .shiny-input-container:first-of-type .control-label { margin-top: 8px; }
    }
  "))

oup_theme <- oup_theme |>
  bs_add_rules(paste0("
    /* Hover cue for Selectize (closed control) */
    .selectize-control.single .selectize-input:hover{
      border-color: ", OUP_BROWN, " !important;
      box-shadow: 0 0 0 .12rem rgba(190,90,22,.35) !important;
      filter: brightness(1.06);
      cursor: pointer;
    }
    /* Hover/active option inside the opened dropdown */
    .selectize-dropdown [data-selectable].option:hover,
    .selectize-dropdown .option.active{
      background: ", OUP_VALUE_BOX, " !important;
      color: ", OUP_TEXT, " !important;
    }
  "))


ui <- page_fluid(
  theme = oup_theme,
  tags$head(
    # Google Fonts (browser loads; no R downloads)
    tags$link(rel = "preconnect", href = "https://fonts.googleapis.com"),
    tags$link(rel = "preconnect", href = "https://fonts.gstatic.com", crossorigin = "anonymous"),
    tags$link(
      href = "https://fonts.googleapis.com/css2?family=Lexend:wght@300;400;500&family=Recursive:wght,MONO@400,1&display=swap",
      rel  = "stylesheet"
    ),
    # iFrame Resizer (safe when embedded)
    tags$script(src = "https://cdn.jsdelivr.net/npm/iframe-resizer/js/iframeResizer.contentWindow.min.js"),
    tags$script(HTML("
      document.addEventListener('shiny:idle', function(){
        if (window.parentIFrame && window.parentIFrame.size) window.parentIFrame.size();
      });
    "))
  ),

  # --- Plot container + “no-moat” helpers (same as crosstab) ---
  tags$head(
    tags$style(HTML("#ciPlot img{display:block;width:100%;height:auto!important;}")),
    tags$script(HTML("
      (function () {
        function send() {
          if (!window.Shiny) return;
          Shiny.setInputValue('vh_px', window.innerHeight, {priority:'event'});
          Shiny.setInputValue('resizeTick', Date.now(),     {priority:'event'});
        }
        window.addEventListener('load', send, {once:true});
        document.addEventListener('shiny:connected', send);
        window.addEventListener('resize', send);
        window.addEventListener('orientationchange', send);
      })();
    ")),
    tags$script(HTML("
      Shiny.addCustomMessageHandler('setCiHeight', function(px){
        var el = document.getElementById('ciPlot');
        if (el) el.style.height = String(px) + 'px';
      });
    "))
  ),

  div(id = "ifr-root", `data-iframe-height` = "true", class = "no-stack",
      # LEFT controls
      div(class = "left",
          sliderInput("n_raw", "Sample size n", min = 3, max = 30, value = 5, step = 1, ticks = FALSE),
          sliderInput("sd", "Sample standard deviation s", min = 0.1, max = 1.0, value = 0.9, step = 0.1, ticks = FALSE),
          selectInput("level", "Confidence level",
                      choices = c("80%"=0.80,"90%"=0.90,"95%"=0.95,"99%"=0.99),
                      selected = 0.95),
          div(class = "sidebar-title", "Colour key"),
          div(class = "legend-item", span(class="legend-dot", style=paste0("background-color:", OUP_RED, ";")),     "Mean (assumed 0)"),
          div(class = "legend-item", span(class="legend-dot", style=paste0("background-color:", OUP_ORANGE, ";")), "CI endpoints"),
          br(),
          actionButton("reset", "Reset to n=5, s=0.9, 95%", class = "btn btn-secondary")
      ),

      # RIGHT plot + footer
      div(class = "right",
          div(id = "plotBox",
              plotOutput("ciPlot"),
              br(),
              div(id = "stats", textOutput("stats"))
          )
      )
  )
)

server <- function(input, output, session) {

  observeEvent(input$reset, {
    updateSliderInput(session, "n_raw", value = 5)
    updateSliderInput(session, "sd",    value = 0.9)
    updateSelectInput(session, "level", selected = 0.95)
  })

  # ---- plot height (same pattern as crosstab) ----
  plotHeight <- reactive({
    w <- session$clientData$output_ciPlot_width
    if (is.null(w) || !is.finite(w) || w <= 0) w <- 360
    compact  <- (w < 520)
    h_from_w <- if (compact) max(240, 0.44 * w) else max(260, min(520, 0.60 * w))

    vh <- input$vh_px
    if (is.numeric(vh) && is.finite(vh) && vh > 0) {
      cap <- if (compact) 0.46 * vh else 0.52 * vh
      h_from_w <- min(h_from_w, cap)
    }
    round(h_from_w)
  })

  observeEvent(list(plotHeight(), input$resizeTick), {
    session$sendCustomMessage('setCiHeight', plotHeight())
  }, ignoreInit = FALSE)

  output$ciPlot <- renderPlot({
    n  <- as.integer(input$n_raw)
    s  <- input$sd
    cl <- as.numeric(input$level)

    df    <- max(n - 1, 1L)
    se    <- s / sqrt(n)
    alpha <- 1 - cl
    tcrit <- qt(1 - alpha/2, df)
    ci    <- tcrit * se
    m     <- 0

    # --- FIXED x-axis (so interval width changes are obvious) ---
    x_min <- -3; x_max <- 3
    xs <- seq(x_min, x_max, length.out = 1600)
    ys <- dt((xs - m)/se, df) / se
    yM <- suppressWarnings(max(ys, na.rm = TRUE)); if (!is.finite(yM) || yM <= 0) yM <- 1e-6

    # Use container width only (robust on iOS first render)
    wcd   <- session$clientData$output_ciPlot_width
    w_use <- if (is.null(wcd) || !is.finite(wcd) || wcd <= 0) 360 else wcd
    tiny  <- (w_use < 420)

    op <- par(no.readonly = TRUE); on.exit(par(op), add = TRUE)
    par(
      fg = OUP_TEXT, col.axis = OUP_TEXT, col.lab = OUP_TEXT, col = OUP_TEXT,
      mar  = if (tiny) c(3.0, 3.2, 1.8, 0.8) else c(4.6, 4.6, 3.0, 1.2),
      mgp  = if (tiny) c(1.9, 0.5, 0)        else c(2.5, 0.8, 0),
      xaxs = if (tiny) "i" else "r",
      yaxs = if (tiny) "i" else "r",
      cex.axis = if (tiny) 0.90 else 1.00,
      cex.lab  = if (tiny) 0.95 else 1.05,
      tck  = -0.015
    )

    plot(xs, ys, type = "n",
         xlab = "", ylab = "Density",
         xlim = c(x_min, x_max),
         ylim = c(0, yM * (if (tiny) 1.06 else 1.14)),
         xaxt = "n", yaxt = "s")
    axis(1, col = NA, col.ticks = OUP_TEXT, lwd = 0, lwd.ticks = 1)
    lines(xs, ys, lwd = 2, col = OUP_ORANGE)

    # Guides
    abline(v = m,      col = OUP_RED,     lwd = 2)   # Mean
    abline(v = m - ci, col = OUP_ORANGE, lwd = 2)   # CI endpoints
    abline(v = m + ci, col = OUP_ORANGE, lwd = 2)

    # Labels (clamped to the fixed x-range so they don't go off-canvas)
    clamp <- function(z, lo = x_min, hi = x_max) pmin(hi, pmax(lo, z))
    usr   <- par("usr")
    y_lab <- usr[4] - (if (tiny) 0.07 else 0.09) * diff(usr[3:4])
    text(clamp(m),       y_lab, "Mean",     col = OUP_RED,     cex = if (tiny) 0.85 else 0.95)
    text(clamp(m - ci),  y_lab, "Lower CI", col = OUP_ORANGE, cex = if (tiny) 0.85 else 0.95)
    text(clamp(m + ci),  y_lab, "Upper CI", col = OUP_ORANGE, cex = if (tiny) 0.85 else 0.95)
  },
  width  = function() {
    w <- session$clientData$output_ciPlot_width
    if (is.null(w) || !is.finite(w) || w <= 0) w <- 360
    round(max(280, min(1100, w)))
  },
  height = function() plotHeight(),
  res = 96, execOnResize = TRUE, bg = OUP_BACKGROUND)

  output$stats <- renderText({
    n  <- as.integer(input$n_raw)
    s  <- input$sd
    cl <- as.numeric(input$level)
    df <- max(n - 1, 1L)
    se <- s / sqrt(n)
    alpha <- 1 - cl
    tcrit <- qt(1 - alpha/2, df)
    ci    <- tcrit * se
    sprintf(
      'n = %d   |   s = %.2f   |   df = %d   |   SE = %.3f   |   t* = %.3f   |   CI half-width = %.3f   |   FULL width = %.3f',
      n, s, df, se, tcrit, ci, 2*ci
    )
  })
}

shinyApp(ui, server)
